    addHTMLElement('div', 'model_size', 'TO', 'info_panel', false);
    setHTMLElemAttribute('innerHTML', ['Model Size: ',Math.min(Math.max(getHTMLElemAttribute('value', 'w_size', false), 0.8), 1.4),'m×',Math.min(Math.max(getHTMLElemAttribute('value', 'd_size', false), 0.7), 1),'m×',Math.min(Math.max(getHTMLElemAttribute('value', 'h_size', false), 0.6), 1),'m'].join(''), 'model_size', false);
    setHTMLElemAttribute('className', 'model_size', 'model_size', false);
